import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Custom CUDA kernel for element-wise addition (float) ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

# Compile the inline CUDA code for element-wise addition
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Custom CUDA kernel for bias addition (float) ----------
bias_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void add_bias_kernel(const float* out, const float* bias, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        out[idx] += bias[idx];
    }
}

torch::Tensor add_bias_cuda(torch::Tensor a, torch::Tensor b) { // b is the bias tensor
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    add_bias_kernel<<<num_blocks, block_size>>>(out.data_ptr<float>(), b.data_ptr<float>(), size);

    return out;
}
"""

bias_add_cpp_source = "torch::Tensor add_bias_cuda(torch::Tensor a, torch::Tensor b);"

# Compile bias addition inline
add_bias = load_inline(
    name="add_bias",
    cpp_sources=bias_add_cpp_source,
    cuda_sources=bias_add_source,
    functions=["add_bias_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv3d = nn.Conv3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
        # Wrap elementwise addition for a+b
        self.elementwise_add = elementwise_add
        # Optionally wrap bias addition (if needed)
        self.add_bias = add_bias

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 3D convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, width, height, depth).

        Returns:
            torch.Tensor: Output tensor after convolution.
        """
        out = self.conv3d(x)
        return out
